
import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { APP_MODES, AppMode, DEPLOYED_CONTRACTS_TEST, DEPLOYED_CONTRACTS_PROD, RPC_CONFIG } from '@core/constants';


@Injectable({
    providedIn: 'root'
})
export class ConfigService {
    private modeSubject = new BehaviorSubject<AppMode>(APP_MODES.TEST);
    public mode$ = this.modeSubject.asObservable();

    private customRpcUrlKey = 'custom_rpc_url';
    private activeContractsSubject = new BehaviorSubject<any>(null);
    public activeContracts$ = this.activeContractsSubject.asObservable();

    constructor() {
        this.loadMode();
    }

    get mode(): AppMode {
        return this.modeSubject.value;
    }

    get isProd(): boolean {
        return this.mode === APP_MODES.PROD;
    }

    get contracts() {
        const defaultContracts = this.isProd ? DEPLOYED_CONTRACTS_PROD : DEPLOYED_CONTRACTS_TEST;
        const currentActive = this.activeContractsSubject.value;
        if (currentActive) {
            return { ...defaultContracts, ...currentActive };
        }
        return defaultContracts;
    }

    updateActiveContracts(newContracts: any) {
        this.activeContractsSubject.next(newContracts);
    }

    get rpcUrl(): string {
        // Check for custom RPC first
        const customRpc = localStorage.getItem(this.customRpcUrlKey);
        if (customRpc && this.validateUrl(customRpc)) {
            return customRpc;
        }
        return RPC_CONFIG[this.mode];
    }

    get chainId(): number {
        return this.isProd ? 1 : 1337;
    }

    setMode(mode: AppMode) {
        localStorage.setItem('app_mode', mode);
        this.modeSubject.next(mode);
    }

    updateRpcUrl(url: string): boolean {
        if (!this.validateUrl(url)) {
            throw new Error('Invalid RPC URL');
        }
        localStorage.setItem(this.customRpcUrlKey, url);
        return true;
    }

    resetRpcUrl() {
        localStorage.removeItem(this.customRpcUrlKey);
    }

    hasCustomRpc(): boolean {
        return localStorage.getItem(this.customRpcUrlKey) !== null;
    }

    validateUrl(url: string): boolean {
        try {
            const urlObj = new URL(url);
            return urlObj.protocol === 'http:' || urlObj.protocol === 'https:';
        } catch {
            return false;
        }
    }

    private loadMode() {
        const saved = localStorage.getItem('app_mode') as AppMode;
        if (saved && Object.values(APP_MODES).includes(saved)) {
            this.modeSubject.next(saved);
        }
    }
}
